<?php declare(strict_types=1); return static fn(PDO $db)=>$db->exec("CREATE TABLE IF NOT EXISTS devis (id INT AUTO_INCREMENT PRIMARY KEY,numero_devis VARCHAR(100) NOT NULL,client_id INT NULL,offre_id INT NULL,statut_devis VARCHAR(30) NOT NULL DEFAULT 'en_attente',delai_livraison_jours INT NULL,total_ht DECIMAL(15,2) NOT NULL DEFAULT 0,total_ttc DECIMAL(15,2) NOT NULL DEFAULT 0,date_emission DATE,date_expiration DATE,archived_at DATETIME NULL,archive_run_id INT NULL,UNIQUE KEY uniq_quote_number(numero_devis),INDEX idx_quote_offer(offre_id),INDEX idx_quote_client(client_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
